{
    "investigate": [
        {
            "tool": "sql",
            "query": "SELECT i.order_id, i.amount, i.vat, i.total, l.amount, l.vat, l.total FROM invoices i JOIN ledger l ON i.order_id = l.order_id WHERE l.vat != l.amount * 0.15 OR l.total != l.amount + l.vat LIMIT 5",
            "why": "Compare invoice values with ledger values to determine if the miscalculation originates in invoice creation (invoice-agent) or ledger sync (sync-job)"
        }
    ],
    "hypotheses": [
        {
            "service": "sync-job",
            "kind": "bad_deploy",
            "mechanism": "Sync-job v1.0.2 deploy at t=481 introduced a bug in ledger synchronization that miscalculates VAT and total values",
            "supporting": ["E1", "E8", "E21"],
            "refuting": ["E20"],
            "explains": ["I3_ledger_integrity"],
            "repair_plan": [
                {"action": "rollback_service", "params": {"service": "sync-job"}},
                {"action": "resync_ledger", "params": {}}
            ]
        },
        {
            "service": "worker",
            "kind": "bad_deploy",
            "mechanism": "Worker v1.0.1 deploy at t=493 caused processing issues leading to queue buildup and worker restarts, though not directly responsible for ledger errors",
            "supporting": ["E4", "E5", "E6", "E9"],
            "refuting": ["E20"],
            "explains": ["E4", "E5", "E6"],
            "repair_plan": [
                {"action": "rollback_service", "params": {"service": "worker"}}
            ]
        }
    ],
    "summary": "Sync-job deploy caused ledger calculation errors while worker deploy caused queue/restart issues"
}
